def _split_shell_words(segment: str) -> list[str]:
    words: list[str] = []
    buf: list[str] = []
    quote: str | None = None
    for i, ch in enumerate(segment):
        if quote:
            buf.append(ch)
            if ch == quote and (i == 0 or segment[i - 1] != '\\'):
                quote = None
            continue
        if ch in {"'", '"'}:
            quote = ch
            buf.append(ch)
            continue
        if ch.isspace():
            if buf:
                words.append(''.join(buf))
                buf = []
            continue
        buf.append(ch)
    if buf:
        words.append(''.join(buf))
    return words

def _strip_shell_pipe_tail(segment: str) -> str:
    words = _split_shell_words(segment)
    out: list[str] = []
    for i, word in enumerate(words):
        if word == '|' and _shell_basename(words[i + 1] if i + 1 < len(words) else '') in _SHELL_PIPE_TAIL_HEADS:
            break
        out.append(word)
    return ' '.join(out).strip()

def _clean_shell_segment(segment: str) -> str:
    words = _split_shell_words(segment)
    out: list[str] = []
    i = 0
    while i < len(words):
        word = words[i]
        if re.match('^\\d*(?:>>?|<)$', word):
            i += 2
            continue
        if re.match('^\\d*(?:>&|<&)\\d+$', word) or re.match('^\\d*>&\\d+$', word):
            i += 1
            continue
        out.append(word)
        i += 1
    return ' '.join(out).strip()

def _is_shell_boundary_echo(segment: str) -> bool:
    words = _split_shell_words(segment)
    if _shell_basename(words[0] if words else '') != 'echo':
        return False
    rest = ' '.join(words[1:])
    return bool(re.search('-{2,}|_exit=|(?:^|\\s|=)\\$[?{]|PIPESTATUS', rest))

